      "shortDescription": "A la salida de Palacios de Valduerna se coge una agradable pista que avanza entre chaparras y jaras. Tras más de seis kilímetros se llega hasta una carretera comacal (en la foto) que hay que seguir por la derecha para abandonarla medio kilómetro desués por...",
      "isWarning": false,
