      "title": "Puente romano de Valimbre. Río Turienzo",
      "slug": "puente-romano-de-valimbre-rio-turienzo",
      "shortDescription": "Último vestigio romano que encuentra el peregrino antes de entrar en Asturica Augusta. Sostenido por cuatro arcos de medio punto con vistosos tajamares aguas arriba fue completamente restaurado a finales de los años 90",
      "isWarning": false,
      "coordinateStatus": "pending",
