      "slug": "celada-de-la-vega-n-vi",
      "shortDescription": "Si tras cruzar el puente de Valimbre continamos de frente llegaremos hasta la N-VI a la altura de Celada de la Vega. Tres kilómetros por el arcén de la carretera nos llevarán hasta la misma Astorga, el fin de la peregrinación por la Vía de la Plata",
      "isWarning": false,
      "coordinateStatus": "pending",
