      "slug": "aeri-de-montserrat",
      "shortDescription": "La escalada en teleférico al Santuario de Monserrates la primera descarga de adrenalina de esta Camino. Se inauguró en 1930 y salva un desnivel de 544 metros en tan solo un tramo de 1.350 metros.",
      "isWarning": false,
      "coordinateStatus": "pending",
