      "title": "Basílica de Montserrat",
      "slug": "basilica-de-montserrat",
      "shortDescription": "El interior de la basílica, entre el gótico y el renacimiento, es del siglo XVI y la fachada principal actual, en la imagen, se construyó en el XX.",
