      "type": "punto",
      "title": "Casa",
      "slug": "casa",
      "shortDescription": "El camino de Santiago abandona Ena por el GR-95, pisando las últimas tierras de la Hoya de Huesca. A la vera del camino se encuentra esta casa habitada (Km 2,1).",
