      "type": "punto",
      "title": "Zona encharcada",
      "slug": "zona-encharcada",
      "shortDescription": "El recorrido entre Ena y Botaya es muy propenso a encharcarse debido a la proximidad del Barroco de Ena y los arroyos que lo alimentan.",
      "isWarning": false,
      "coordinateStatus": "pending",
